from pathlib import Path
p=Path(__file__).resolve().parent
f=p/'build_eager_prefix_overlay.py'
s=f.read_text(encoding='utf-8-sig')
s=s.replace("    def accept(text):\n", "    def accept(text):\n        text = once(text, '        new_seq_lens = None\\n', '''        if candidates.shape[1] != int(self.block_size):\n            expected_rows = bs * candidates.shape[1]\n            if target_predict is not None:\n                if target_predict.numel() != expected_rows:\n                    raise ValueError(\"DFLASH prefix predictions retain padding\")\n            elif next_token_logits.shape[0] != expected_rows:\n                raise ValueError(\"DFLASH prefix logits retain padding\")\n        new_seq_lens = None\n''')\n")
s=s.replace("        after = once(after, 'hidden.view(bs, int(self.block_size), -1)', 'hidden.view(bs, verify_block_size, -1)')", "        after = once(after, '        hidden = hidden.view(bs, int(self.block_size), -1)\\n', '''        if verify_block_size != block_size and (\n            hidden.ndim != 2 or hidden.shape[0] != bs * verify_block_size\n        ):\n            raise ValueError(\"DFLASH prefix aux rows retain padding\")\n        hidden = hidden.view(bs, verify_block_size, -1)\n''')")
f.write_text(s)
f=p/'test_prefix_worker_tail.py';s=f.read_text(encoding='utf-8-sig')
s=s.replace('import itertools\n','import itertools\nfrom functools import lru_cache\n')
s=s.replace('import torch\n','import torch\ntorch.set_num_threads(1)\n')
s=s.replace('def get_worker_class(candidate):','@lru_cache(maxsize=2)\ndef get_worker_class(candidate):')
s=s.replace('def make_fixture(bs, width, generation, candidate, triton_model=True, fallback=False):','def make_fixture(bs, width, generation, candidate, triton_model=True, fallback=False, cpu_lengths=True, padded=False, trim=False, reject=False):')
s=s.replace('batch=NS(forward_mode=scaffold.ForwardMode.DECODE,seq_lens=prefix,seq_lens_cpu=prefix.clone(),','batch=NS(forward_mode=scaffold.ForwardMode.DECODE,seq_lens=prefix,seq_lens_cpu=prefix.clone() if cpu_lengths else None,')
s=s.replace("        return NS(logits_output=NS(next_token_logits=logits,hidden_states=hidden),\n", "        output=NS(next_token_logits=logits,hidden_states=hidden)\n        if padded:\n            output.next_token_logits=torch.cat([logits,torch.full((5,1024),float('nan'))])\n            output.hidden_states=torch.cat([hidden,torch.full((5,13),float('nan'))])\n        if trim:\n            source_trim(fb,output,bs)\n        return NS(logits_output=output,\n")
s=s.replace("    result=worker.tail(batch,bs,8,ids,positions.flatten(),positions,slots.flatten(),slots,plan,prefix,NS(),publish,None,None)", "    draft_input=NS(nxt_kv_lens_cpu=prefix.cpu()+16,nxt_kv_lens_sum=int((prefix+16).sum()))\n    try:\n        result=worker.tail(batch,bs,8,ids,positions.flatten(),positions,slots.flatten(),slots,plan,prefix,draft_input,publish,None,None)\n    except ValueError as error:\n        if reject:\n            assert 'retain padding' in str(error)\n            return {'rejected':True}\n        raise\n    assert not reject, 'padded outputs were admitted'\n    assert (batch.seq_lens_cpu is not None)==cpu_lengths")
s=s.replace("def main():\n", "def build_source_trim():\n    path=SRT/'model_executor/forward_batch_info.py'\n    fn=find(path,'post_forward_mlp_sync_batch','ForwardBatch')\n    branch=next(n for n in ast.walk(fn) if isinstance(n,ast.If) and ast.unparse(n.test)=='self.forward_mode.is_target_verify()')\n    trim=ast.FunctionDef(name='trim',args=ast.arguments(posonlyargs=[],args=[ast.arg(arg=n) for n in ('self','logits_output','bs')],kwonlyargs=[],kw_defaults=[],defaults=[]),body=branch.body,decorator_list=[])\n    ns={}\n    scaffold.load([trim],ns)\n    return ns['trim']\n\nsource_trim=build_source_trim()\n\ndef main():\n")
s=s.replace("    report['sources']=", "    report['padded_post_forward_cases']=0\n    report['untrimmed_padding_rejections']=0\n    report['no_cpu_length_cases']=0\n    for bs,w in itertools.product((1,3,17),(1,2,4,6)):\n        make_fixture(bs,w,2,True,True,cpu_lengths=False)\n        report['no_cpu_length_cases']+=1\n        make_fixture(bs,w,2,True,True,padded=True,trim=True)\n        report['padded_post_forward_cases']+=1\n        make_fixture(bs,w,2,True,True,padded=True,reject=True)\n        report['untrimmed_padding_rejections']+=1\n    report['sources']=")
f.write_text(s)
print('Updated isolated source row guards and padding/host-bound controls')
